import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();

        // Helper functions for modular addition and multiplication
        java.util.function.BiFunction<Integer, Integer, Integer> addMod = (a, b) -> (a + b) % mod;
        java.util.function.BiFunction<Integer, Integer, Integer> mulMod = (a, b) -> (a * b) % mod;

        int[] mem = new int[n + 1];
        mem[0] = 0;
        mem[1] = 1;
        int total = 1;

        for (int i = 2; i <= n; i++) {
            int sqrtLimit = (int) Math.sqrt(i) + 1;
            int current = total;

            for (int f = 2; f < sqrtLimit; f++) {
                current = addMod.apply(current, mem[i / f]);
            }

            int boundary = i;
            for (int j = 1; j <= i / sqrtLimit; j++) {
                int nxt = i / (j + 1);
                current = addMod.apply(current, mulMod.apply(boundary - nxt, mem[j]));
                boundary = nxt;
            }

            total = addMod.apply(total, current);
            mem[i] = current;
        }

        System.out.println(mem[n]);
        scanner.close();
    }
}
